import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for start, end, _ in jobs for t in (start, end)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)
    sink = m - 1

    graph: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(idx[start], idx[end], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        for v, cap, cost, _ in graph[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    flow = 0
    total_cost = 0

    while flow < k:
        dist = [INF] * m
        dist[0] = 0
        prev_node = [-1] * m
        prev_edge = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(graph[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        prev_node[v] = u
                        prev_edge[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[sink] >= 0:
            break

        add = k - flow
        v = sink
        while v != 0:
            u = prev_node[v]
            cap = graph[u][prev_edge[v]][1]
            if cap < add:
                add = cap
            v = u

        v = sink
        while v != 0:
            u = prev_node[v]
            edge = graph[u][prev_edge[v]]
            edge[1] -= add
            graph[v][edge[3]][1] += add
            v = u

        flow += add
        total_cost += add * pot[sink]

    return -total_cost
